<div class="section-head"><div><h2>Manage announcements</h2><p class="muted">Create, update, and archive updates for contests you own.</p></div></div>
<section class="grid grid-2"><form class="card grid" method="post" action="<?=e(url('/organizer/announcements'))?>"><?=csrf_field()?><h2>New announcement</h2><div class="field"><label for="contest_id">Contest</label><select id="contest_id" name="contest_id"><?php foreach($contests as $c):?><option value="<?=e($c['contest_id'])?>"><?=e($c['contest_title'])?></option><?php endforeach;?></select></div><div class="field"><label for="title">Title</label><input id="title" name="title" maxlength="150" required></div><div class="field"><label for="message">Message</label><textarea id="message" name="message" maxlength="2000" required></textarea></div><button class="button">Publish announcement</button></form>
<div class="grid"><?php foreach($announcements as $a):?><article class="card"><form class="grid" method="post" action="<?=e(url('/organizer/announcements'))?>"><?=csrf_field()?><input type="hidden" name="announcement_id" value="<?=e($a['announcement_id'])?>"><input type="hidden" name="contest_id" value="<?=e($a['contest_id'])?>"><span class="eyebrow"><?=e($a['contest_title'])?></span><div class="field"><label for="title-<?=e($a['announcement_id'])?>">Title</label><input id="title-<?=e($a['announcement_id'])?>" name="title" value="<?=e($a['announcement_title'])?>" maxlength="150" required></div><div class="field"><label for="message-<?=e($a['announcement_id'])?>">Message</label><textarea id="message-<?=e($a['announcement_id'])?>" name="message" maxlength="2000" required><?=e($a['message'])?></textarea></div><button class="button">Save changes</button></form><form method="post" action="<?=e(url('/organizer/announcements/'.$a['announcement_id'].'/archive'))?>" data-confirm="Archive this announcement?"><?=csrf_field()?><button class="button-danger button-block">Archive</button></form></article><?php endforeach;?><?php if(!$announcements):?><article class="card empty">No announcements.</article><?php endif;?></div></section>

